(()=>{'use strict';
 const art=window.VoidCollectibleArt,$=id=>document.getElementById(id),escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let rows=art?.items?.()||[],focus=null,ticket=0,selected=null;const dialog=$('ar-dialog');
 function paint(){const q=$('ar-search').value.trim().toLocaleLowerCase(),series=$('ar-series').value,visible=rows.filter(a=>(series==='all'||a.series===series)&&(!q||[a.name,a.series,a.material,a.alt].join(' ').toLocaleLowerCase().includes(q)));$('ar-count').textContent=`${visible.length} objects · ${rows.filter(a=>a.type==='badge').length} decorative badges · ${rows.filter(a=>a.type==='gift').length} gifts · ${rows.filter(a=>a.type==='earned').length} earned awards`;$('ar-grid').innerHTML=visible.map(a=>`<button class="ar-card" data-art-open="${a.id}">${art.render(a.id)}<strong>${escape(a.name)}</strong><small>${escape(a.series)}${a.type==='earned'?' · Earned award':''}</small></button>`).join('')||'<p>No matching objects.</p>';}
 function open(id,button){const a=rows.find(a=>a.id===id);if(!a)return;art.stopAll();ticket++;selected=a;focus=button;$('ar-stage').innerHTML=art.detail(id);$('ar-title').textContent=a.name;$('ar-detail-series').textContent=a.series;$('ar-alt').textContent=a.alt;$('ar-material').textContent=a.material;$('ar-inline').innerHTML=[16,20,24].map(size=>`<span>${art.render(id,true)}${size}px</span>`).join('');$('ar-download').href=a.detailURL;$('ar-download').download=id+'.svg';$('ar-status').textContent='Static resting pose';dialog.showModal();art.mount($('ar-stage'),id,{detail:true});}
 $('ar-grid').addEventListener('click',event=>{const button=event.target.closest?.('[data-art-open]');if(button)open(button.dataset.artOpen,button);});
 $('ar-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{ticket++;art.stopAll();selected=null;if(focus?.isConnected)focus.focus();});
 $('ar-play').addEventListener('click',async()=>{if(!selected)return;const current=++ticket,id=selected.id;$('ar-status').textContent='Preparing preview…';const result=await art.preview($('ar-stage'),id,{detail:true});if(current!==ticket||!dialog.open){result.stop?.();return;}$('ar-status').textContent=result.played?'Playing once · opening effect only':'Static image shown · motion is reduced or unavailable';if(result.played)result.finished?.then(()=>{if(current===ticket&&dialog.open)$('ar-status').textContent='Preview complete';});});
 $('ar-search').addEventListener('input',paint);$('ar-series').addEventListener('change',paint);$('ar-reduce').addEventListener('change',()=>{ticket++;art.stopAll();window.VoidTheme?.apply({reducedMotion:$('ar-reduce').checked});$('ar-status').textContent='Static resting pose';});
 for(const series of [...new Set(rows.map(a=>a.series))]){const option=document.createElement('option');option.value=series;option.textContent=series;$('ar-series').append(option);}paint();
})();
